/** Which network a field belongs to, from its label or its address.
 *
 *  Table-driven rather than a chain of ifs: the marks carry the strings that
 *  identify them, so adding a network is one entry rather than two places to
 *  keep in step. Order is the order above, so anything that would be swallowed
 *  by a shorter name sits in front of it.
 */
export function socialOf(label: string, value: string): Social {
  const hay = `${label} ${value}`.toLowerCase();
  // "X" as a bare label matches nothing useful as a substring.
  if (label.trim().toLowerCase() === "x") return "x";
  for (const [key, mark] of Object.entries(MARKS)) {
    if (mark.match.some((needle) => hay.includes(needle))) return key as Social;
  }
  return "link";
}

export function SocialMark({ name, className = "size-5" }: { name: Social; className?: string }) {
  const mark = MARKS[name];
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" role="img" aria-label={mark.title} className={className}>
      <path d={mark.path} />
    </svg>
  );
}
